ass="nav-link" href="#tid-azWcBR" goto="tid-azWcBR" onclick="return false;">&nbsp;&nbsp;&nbsp;&nbsp;新奇的 Python 库</a></li><li class="nav-item"><a class="nav-link" href="#tid-kZQRiD" goto="tid-kZQRiD" onclick="return false;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;常见问题解决方案</a></li><li class="nav-item"><a class="nav-link" href="#tid-2PF6XZ" goto="tid-2PF6XZ" onclick="return false;">&nbsp;&nbsp;&nbsp;&nbsp;做项目可能会用到的</a></li><li class="nav-item"><a class="nav-link" href="#tid-AKtnwE" goto="tid-AKtnwE" onclick="return false;">&nbsp;&nbsp;&nbsp;&nbsp;数据库相关</a></li><li class="nav-item"><a class="nav-link" href="#tid-dTR4wE" goto="tid-dTR4wE" onclick="return false;">&nbsp;&nbsp;&nbsp;&nbsp;新人写的不着调工具类</a></li><li class="nav-item"><a class="nav-link" href="#tid-tyhA7T" goto="tid-tyhA7T" onclick="return false;">&nbsp;&nbsp;&nbsp;&nbsp;很low的基础习题集</a></li><li class="nav-item"><a class="nav-link" href="#tid-ZjDPQ5" goto="tid-ZjDPQ5" onclick="return false;">接口自动化</a></li><li class="nav-item"><a class="nav-link" href="#tid-Ky58PE" goto="tid-Ky58PE" onclick="return false;">&nbsp;&nbsp;&nbsp;&nbsp;常见问题解决方案</a></li><li class="nav-item"><a class="nav-link" href="#tid-Xenj8p" goto="tid-Xenj8p" onclick="return false;">Pytest+Allure</a></li><li class="nav-item"><a class="nav-link" href="#tid-aFNJjM" goto="tid-aFNJjM" onclick="return false;">&nbsp;&nbsp;&nbsp;&nbsp;实战小项目</a></li><li class="nav-item"><a class="nav-link" href="#tid-F3EhCk" goto="tid-F3EhCk" onclick="return false;">UI 自动化</a></li><li class="nav-item"><a class="nav-link" href="#tid-pRcTdb" goto="tid-pRcTdb" onclick="return false;">APP 自动化</a></li><li class="nav-item"><a class="nav-link" href="#tid-RzmaJQ" goto="tid-RzmaJQ" onclick="return false;">&nbsp;&nbsp;&nbsp;&nbsp;常见问题解决方案</a></li><li class="nav-item"><a class="nav-link" href="#tid-cdJnXf" goto="tid-cdJnXf" onclick="return false;">RobotFramework</a></li><li class="nav-item"><a class="nav-link" href="#tid-PRxWAA" goto="tid-PRxWAA" onclick="return false;">Flask</a></li><li class="nav-item"><a class="nav-link" href="#tid-TFjnGf" goto="tid-TFjnGf" onclick="return false;">&nbsp;&nbsp;&nbsp;&nbsp;常见问题解决方案</a></li><li class="nav-item"><a class="nav-link" href="#tid-5NanAC" goto="tid-5NanAC" onclick="return false;">FastAPI</a></li> </ul> </nav> </div><span class="articleSuffix-flg"> <br><p class="essaySuffix-eof">__EOF__</p> <div id="articleSuffix"> <div class="articleSuffix-bg"></div> <div class="articleSuffix-left"> <a data-fancybox="gallery" href="https://files.cnblogs.com/files/poloyy/touxianga.bmp"><img src="https://files.cnblogs.com/files/poloyy/touxianga.bmp"></a> </div> <div class="articleSuffix-right"> </div> <div style="clear:both"></div> </div> </span></div>`,
    },
  },
  setup() {
    const preview = ref(null); // 预览组件 ref
    const scrollbar = ref(null); // 菜单滚动条 ref
    const titles = reactive([]); // 目录列表
    const showBackTop = ref(false); // 是否显示回顶部
    const tocTop = ref(304); // 菜单置顶距离

    onMounted(() => {
      // 锚点菜单
      const anchors = preview.value.$el.querySelectorAll('h2,h3,h4');
      const aTitles = Array.from(anchors).filter((title) => !!title.innerText.trim());

      if (aTitles.length) {
        const hTags = Array.from(new Set(aTitles.map((title) => title.tagName))).sort();
        let sum = 0;
        titles.splice(
          0,
          aTitles.length,
          ...aTitles.map((el) => {
            ++sum;
            const id = 'article-content-toc-titles-id-' + sum;
            el.setAttribute('id', id);
            return {
              title: el.innerText,
              href: '#' + id,
              indent: hTags.indexOf(el.tagName),
            };
          })
        );
      }

      // 菜单高度滚动监听;
      const page = document.querySelector('#app > div.article');
      showBackTop.value = page.scrollTop > 288;
      page.onscroll = function (e) {
        scrollbar.value.update();
        showBackTop.value = e.target.scrollTop > 288;
        tocTop.value = Math.max(16, 304 - e.target.scrollTop);
      };
    });

    return {
      preview,
      scrollbar,
      titles,
      tocTop,
      showBackTop,
    };
  },
});
</script>

